const lessonPositions={};
function lessonRecord(id){return state.lessons[id]||{};}
function lessonDone(id){const m=learningModules.find(m=>m.id===id),r=lessonRecord(id);return !!m&&m.cases.every((c,i)=>Number.isInteger(r[i])&&r[i]>=0&&r[i]<c.options.length);}
function lessonStats(id){const m=learningModules.find(m=>m.id===id),r=lessonRecord(id);return {answered:m.cases.filter((c,i)=>Number.isInteger(r[i])&&r[i]>=0&&r[i]<c.options.length).length,correct:m.cases.filter((c,i)=>r[i]===c.correct).length};}
function extraCards(){return catalogModules().slice(3).map(renderModuleCard).join('');}
function lessonResultRows(){return learningModules.map(m=>{const s=lessonStats(m.id);return `<tr><td>${m.title}</td><td>${lessonDone(m.id)?'Completado':s.answered?'En práctica':'Pendiente'}</td><td>${s.correct}/${s.answered} aciertos · ${s.answered}/3 revisados</td></tr>`;}).join('');}
function lessonCSVRows(){const rows=[[],['Módulos de ampliación','Caso','Respuesta','Correcta']];learningModules.forEach(m=>m.cases.forEach((c,i)=>{const a=lessonRecord(m.id)[i];rows.push([m.title,i+1,Number.isInteger(a)?c.options[a]:'Pendiente',Number.isInteger(a)?(a===c.correct?'Sí':'No'):'']);}));return rows;}
