const historyExamples={
 'Los primeros signos ocultos en Egipto':'Los signos no convencionales no funcionan como el cifrado César: no dependen de una clave matemática. Aun así, enseñan que una escritura puede apartarse de la forma cotidiana para limitar o dirigir su lectura.',
 'Secretos de oficio en Mesopotamia':'Una receta técnica podía tener valor para un taller. Hacerla difícil de interpretar protegía parte del conocimiento de quien la había escrito.',
 'La escítala espartana':'Si la tira se separaba de la vara, las letras parecían desordenadas. Al enrollarla en una vara del mismo tamaño, el mensaje recuperaba su forma.',
 'El cifrado de César':'Con un desplazamiento de tres posiciones, A se convierte en D, B en E y así sucesivamente. Es fácil de entender, pero también de probar con todas sus claves.',
 'Al-Kindi y el análisis de frecuencias':'Si una letra aparece muchas veces en un idioma, contar sus repeticiones puede dar pistas sobre el texto original. El análisis de patrones se convirtió en una herramienta de criptoanálisis.',
 'Alberti y los alfabetos múltiples':'En vez de usar siempre el mismo alfabeto, un sistema puede alternar varios. Eso dificulta que una letra frecuente revele directamente su equivalente.',
 'Secretos antes de los computadores':'Una persona que interceptaba una carta podía leerla si no conocía el método de protección. Los sistemas manuales dependían de mantener el procedimiento o la clave lejos de terceros.',
 'Enigma y la Bombe británica':'El reto era reconstruir las posiciones diarias de los rotores. Es un ejemplo de cómo un sistema puede parecer complejo y, aun así, ser analizado.',
 'Una nueva forma de compartir secretos':'En un intercambio de claves, dos participantes pueden acordar un secreto a través de un canal público. Después pueden usarlo para proteger su conversación.',
 'DES: un estándar común':'Cuando muchos sistemas emplean una regla compartida, pueden comunicarse entre sí. Con el tiempo, una clave demasiado corta deja de resistir los equipos modernos.',
 'RSA y las claves públicas':'La clave pública sirve para una operación que cualquiera puede realizar; la privada se guarda. En la práctica, los sistemas combinan varias técnicas en vez de usar RSA para todo.',
 'El gusano Morris y el nacimiento de CERT/CC':'Si una red presenta un problema, se necesitan personas que investiguen, avisen a otros y coordinen una respuesta. La prevención y la recuperación trabajan juntas.',
 'AES: una nueva generación de cifrado':'Tu práctica AES-GCM añade un valor aleatorio para que repetir el mismo mensaje no produzca necesariamente la misma salida. Ese valor acompaña al cifrado para poder recuperarlo.',
 'Un marco para gestionar riesgos':'Una escuela puede inventariar sus equipos, proteger cuentas, detectar problemas, preparar avisos y guardar copias para recuperar trabajos.',
 'Cloudflare y la entropía de LavaRand':'El movimiento de las burbujas, las sombras y el ruido de la cámara aportan cambios difíciles de predecir. LavaRand convierte esa observación en datos aleatorios y los combina con otras fuentes; las lámparas ayudan a crear aleatoriedad, pero no reemplazan algoritmos como AES o protocolos como TLS.',
 'TLS 1.3 protege las comunicaciones':'Cuando visitas una página por HTTPS, TLS protege el trayecto. Aun así, revisa a qué sitio estás entrando antes de enviar información.',
 'Coordinación de la seguridad digital':'Compartir una alerta a tiempo permite que otras organizaciones revisen sus sistemas y actúen antes de que un problema se extienda.',
 'Prepararse para la era cuántica':'Una firma digital permite comprobar quién aprobó un mensaje y si cambió. Los nuevos estándares se preparan para riesgos futuros.'
};
function breachesView(){return `<section class="breach-section" id="grandes-incidentes" aria-labelledby="breach-title"><div class="breach-heading"><div><span class="eyebrow">CASOS QUE CAMBIARON LA SEGURIDAD DIGITAL</span><h2 id="breach-title">Grandes incidentes y robos de información</h2><p>Una filtración afecta a personas reales. Estos casos muestran qué ocurrió y qué podemos aprender, sin explicar cómo cometer un ataque.</p></div><span class="breach-count">4 casos documentados</span></div><div class="breach-grid">${breachCases.map(c=>`<article class="breach-card card"><img src="./imagenes/${c.image}" alt="${c.alt}" loading="lazy" width="560" height="230"><div class="breach-card-body"><span class="breach-year">${c.year}</span><h3>${c.name}</h3><p>${c.summary}</p><details><summary>Conoce el contexto y la lección</summary><p>${c.detail}</p><p class="breach-lesson"><b>¿Qué aprendemos?</b> ${c.lesson}</p></details><a class="inline-link source-link" href="${c.url}" target="_blank" rel="noopener noreferrer">Consultar fuente: ${c.source} ↗</a></div></article>`).join('')}</div></section>`;}
let historyFilter='todos';
function historyView(){
 const events=historyEvents.filter(e=>historyFilter==='todos'||e.category===historyFilter);
 const counts={todos:historyEvents.length,cifrado:historyEvents.filter(e=>e.category==='cifrado').length,seguridad:historyEvents.filter(e=>e.category==='seguridad').length};
 return head('Historia / Del secreto a la confianza digital','Las ideas que cambiaron nuestra seguridad.','Explora el cifrado, la criptografía y la ciberseguridad a través de imágenes, ejemplos y fuentes originales.',`${historyEvents.length} hitos`)+`<section class="history-intro"><div><span class="eyebrow">HISTORIA ILUSTRADA</span><h2>De los mensajes secretos a los sistemas conectados.</h2></div><p>El <b>cifrado</b> transforma datos con una clave. La <b>criptografía</b> estudia técnicas como el cifrado, las firmas y el intercambio de claves. La <b>ciberseguridad</b> protege sistemas, personas y datos con tecnología, procesos y buenas decisiones.</p><button class="history-jump" id="history-jump" type="button">Explorar grandes incidentes ↓</button></section><div class="history-concepts" aria-label="Conceptos de la historia"><div><b>01 · Cifrado</b><span>Hacer ilegible un mensaje para quien no tenga la clave.</span></div><div><b>02 · Criptografía</b><span>Estudiar y diseñar formas de proteger y verificar información.</span></div><div><b>03 · Ciberseguridad</b><span>Prevenir, detectar y responder a riesgos digitales.</span></div></div><section class="cloudflare-lavarand card" aria-labelledby="lavarand-title"><div class="cloudflare-lavarand-copy"><span class="eyebrow">CASO REAL · 2017</span><h2 id="lavarand-title">Las lámparas de lava de Cloudflare</h2><p>Una lámpara de lava no cifra mensajes. Su movimiento cambia de forma difícil de predecir; una cámara registra esas variaciones y LavaRand las transforma en <b>entropía</b>, es decir, una fuente de aleatoriedad.</p><div class="cloudflare-steps"><div><b>1 · Observar</b><span>Burbujas, sombras y ruido del sensor generan cambios únicos.</span></div><div><b>2 · Mezclar</b><span>La señal se combina con otras fuentes de aleatoriedad del sistema.</span></div><div><b>3 · Proteger</b><span>La semilla resultante ayuda a generar números aleatorios para claves y conexiones seguras.</span></div></div><a class="inline-link source-link" href="https://blog.cloudflare.com/randomness-101-lavarand-in-production/" target="_blank" rel="noopener noreferrer">Fuente oficial de Cloudflare ↗</a></div><div class="cloudflare-lavarand-visuals"><img src="./imagenes/historia-lavarand.svg" alt="Pared de lámparas de lava observada por una cámara" loading="lazy" width="560" height="230"><img src="./imagenes/historia-entropia.svg" alt="Flujo visual desde la aleatoriedad hasta un escudo de seguridad" loading="lazy" width="560" height="230"></div></section>${breachesView()}<div class="history-filters" role="group" aria-label="Filtrar la historia">${[['todos','Toda la historia'],['cifrado','Cifrado y criptografía'],['seguridad','Ciberseguridad']].map(([id,t])=>`<button type="button" class="btn ${historyFilter===id?'':'ghost'}" data-history-filter="${id}" aria-pressed="${historyFilter===id}">${t} <span class="filter-count">${counts[id]}</span></button>`).join('')}</div><p class="muted history-count" role="status">${events.length} ${events.length===1?'acontecimiento':'acontecimientos'} en esta sección</p><ol class="timeline">${events.map(e=>{const media=historyMedia[e.title],example=historyExamples[e.title];return `<li class="timeline-event"><div class="timeline-year">${e.year}</div><article class="card"><img class="history-image" src="./imagenes/${media[0]}" alt="${media[1]}" loading="lazy" width="560" height="230"><div class="history-card-body"><span class="eyebrow">${e.category==='cifrado'?'Cifrado y criptografía':'Ciberseguridad'}</span><h2>${e.title}</h2><p>${e.summary}</p><p class="history-example"><b>Para entenderlo:</b> ${example}</p><details><summary>¿Por qué fue importante?</summary><p>${e.impact}</p>${e.route?`<p>${btn('Conéctalo con la práctica',e.route,'ghost')}</p>`:''}</details><a class="inline-link source-link" href="${e.url}" target="_blank" rel="noopener noreferrer">Consultar fuente: ${e.source} ↗</a></div></article></li>`;}).join('')}</ol><div class="notice">Ilustraciones originales y esquemáticas: ayudan a explicar los conceptos, no reproducen fotografías históricas. Los hitos y explicaciones se pueden leer sin conexión; las fuentes externas necesitan internet.</div>`;
}

/* Etapas de aprendizaje: una idea o una decisión por pantalla. */
let activeStage=0;
function learningView(id){return extraFlow(id);}
function bindLearning(route){if(route==='historia'){$$('[data-history-filter]').forEach(b=>b.onclick=()=>{historyFilter=b.dataset.historyFilter;render();});on('#history-jump','click',()=>$('#grandes-incidentes')?.scrollIntoView({behavior:'smooth',block:'start'}));}}
